fields.InputDefinition:
{
  "goal": "Assume you are already logged in at http://localhost:4200. Open the application switcher dropdown next to the logo, select the Lists application, and open the 'Categories' section in its left nav. In the left 'Categories' tree panel, click a category node. Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away. Success is that clicking a category populates the right-hand 'Category Details' panel — showing the category Name, its Parent Category (or '(Top Level)'), and the Lists / Subcategories stat counts. If there are no categories yet, the 'No Categories Yet' empty state rendering is also a valid success.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 35,
  "judgeValidationCriteria": [
    "The Categories tree lists at least one category node OR a valid 'No Categories Yet' empty state is shown",
    "Selecting a category node fills the 'Category Details' panel with its Name, Parent Category value, and the Lists / Subcategories stat counts (member list names appear when the category has lists)",
    "No error messages, blank screens, or crash pages"
  ]
}
